using System;

namespace NEXUS.Security;

public static class ResolutionGuide
{
    public static FindingResolution Enrich(SecurityFinding finding, FindingResolution action)
    {
        var guide = action.Id switch
        {
            "thermal" => (
                "В текущем снимке температура превысила порог NEXUS. Это может быть нагрузка, перекрытая вентиляция или проблема охлаждения; один снимок не устанавливает причину.",
                "1. Откройте температуры и посмотрите имя датчика и график.\n2. В процессах найдите приложения с высокой CPU/GPU-нагрузкой; сохраните работу и закройте ненужные приложения штатно.\n3. Поставьте ноутбук на твёрдую поверхность, освободите вентиляционные отверстия.\n4. Посмотрите температуру после снижения нагрузки. Если она остаётся высокой, проверьте вентиляторы и обратитесь за обслуживанием охлаждения.",
                "Повторите диагностику при сопоставимой нагрузке и посмотрите график. Снижение температуры в простое не подтверждает исправность под нагрузкой."),
            "backup" => (
                "Датчик сообщает о снижении остаточного ресурса накопителя. Очистка файлов освобождает место, но не восстанавливает ресурс SSD.",
                "1. Скопируйте важные файлы на другой физический носитель или в облако.\n2. Откройте несколько файлов из копии и убедитесь, что они читаются.\n3. В утилите производителя проверьте SMART, модель диска и предупреждения о состоянии.\n4. При ухудшении показателей или ошибках чтения планируйте замену накопителя; до проверки избегайте ненужных интенсивных записей.",
                "Убедитесь, что резервная копия пригодна для восстановления. Запишите SMART до/после; после замены проверьте новый накопитель. Предупреждение о ресурсе старого диска может сохраниться."),
            "temp" => (
                "На указанном диске мало свободного места. Temp — лишь один возможный источник; пользовательский Temp может находиться на другом диске.",
                "1. Сверьте букву диска в основании находки.\n2. Выполните анализ Temp и просмотрите список перед удалением.\n3. Подтвердите удаление только предложенных старых временных файлов.\n4. В параметрах хранилища указанного диска проверьте крупные приложения и личные файлы; переносите или удаляйте их после проверки. Корзину очищайте после просмотра содержимого.",
                "Повторите диагностику и сравните занятость именно указанного диска. Если места почти не прибавилось, исследуйте категории хранилища, а не повторяйте очистку Temp."),
            "ram" => (
